var geometry = new api.THREE.BoxGeometry(1, 1, 1);
                var material = new api.THREE.MeshPhongMaterial({ color: 0xE8593C });
                var cube = new api.THREE.Mesh(geometry, material);
                api.group.add(cube);
                return {
                  update: function(t) {
                    cube.rotation.x = t * 0.02;
                    cube.rotation.y = t * 0.03;
                  }
                };

var margin = 40;
                return {
                  draw: function(ctx, W, H, t, dt) {
                    ctx.fillStyle = '#F5F0E8';
                    ctx.fillRect(0, 0, W, H);
                    var originX = margin, originY = H - margin;
                    var axisW = W - 2 * margin, axisH = H - 2 * margin;
                    ctx.strokeStyle = '#333333';
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.moveTo(originX, originY);
                    ctx.lineTo(originX + axisW, originY);
                    ctx.moveTo(originX, originY);
                    ctx.lineTo(originX, originY - axisH);
                    ctx.stroke();
                    function vAt(frac) { return 0.3 + 0.5 * frac; }
                    var nRects = 10;
                    var frac = (Math.sin(t * 0.02) + 1) / 2;
                    var fillUpTo = Math.max(1, Math.floor(frac * nRects));
                    for (var i = 0; i < fillUpTo; i++) {
                      var f0 = i / nRects;
                      var barH = vAt(f0) * axisH * 0.7;
                      var barX = originX + f0 * axisW;
                      var barW = axisW / nRects;
                      ctx.fillStyle = 'rgba(232,89,60,0.5)';
                      ctx.fillRect(barX, originY - barH, barW, barH);
                      ctx.strokeStyle = '#E8593C';
                      ctx.strokeRect(barX, originY - barH, barW, barH);
                    }
                    ctx.strokeStyle = '#4A90D9';
                    ctx.lineWidth = 3;
                    ctx.beginPath();
                    for (var j = 0; j <= nRects; j++) {
                      var fx = j / nRects;
                      var py = originY - vAt(fx) * axisH * 0.7;
                      var px = originX + fx * axisW;
                      if (j === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
                    }
                    ctx.stroke();
                  }
                };
